	@Test
	void oneUnitCannotOpenAndCostAnUnboundedNumberOfProviderEvents() {
		AtomicInteger opened = new AtomicInteger();
		AtomicInteger estimated = new AtomicInteger();
		AtomicInteger closed = new AtomicInteger();
		PackedCostModel provider = new PackedCostModel() {
			@Override
			public double estimateRows(PackedQueryView query, int relationId) {
				throw new AssertionError("the session should own this estimate");
			}

			@Override
			public PackedCostSession openSession(PackedQueryView query) {
				opened.incrementAndGet();
				return new PackedCostSession() {
					@Override
					public void estimateLeaf(int relationId, PackedCostContext context, PackedCostEstimate output) {
						estimated.incrementAndGet();
						output.setRows(1.0d, 1.0d);
					}

					@Override
					public void appendFactor(int relationId, PackedCostContext context, PackedCostEstimate output) {
						estimated.incrementAndGet();
						output.setRows(1.0d, 1.0d);
					}

					@Override
					public void refineOperator(int relationId, PackedCostContext context, PackedCostEstimate output) {
						estimated.incrementAndGet();
					}

					@Override
					public void close() {
						closed.incrementAndGet();
					}
				};
			}
		};
		TupleExpr source = new Join(
				new StatementPattern(Var.of("a"), Var.of("p"), Var.of("b")),
				new StatementPattern(Var.of("b"), Var.of("q"), Var.of("c")));

		PackedPlanningResult result = PackedCascadesPlanner.optimize(source, OptimizationGoal.root(),
				new PackedPlannerLimits(1L, Long.MAX_VALUE, PackedPlannerLimits.DEFAULT_MAX_RETAINED_BYTES, 1L),
				provider);

		assertEquals(PackedSearchCompletionStatus.INCOMPLETE_WORK_LIMIT, result.completionStatus());
		assertTrue(opened.get() + estimated.get() <= 1,
				"one admitted unit cannot cover a session open and provider estimates: opens=" + opened.get()
						+ ", estimates=" + estimated.get());
		assertEquals(opened.get(), closed.get(), "every admitted session must be closed");
		assertEquals(source.getBindingNames(), result.selectedPlan().getBindingNames());
	}

